#include <iostream>
using namespace std;

// Function to check if a number is prime using recursion
bool isPrime(int n, int divisor = 2) {
    // Base cases
    if (n <= 1) return false;
    if (n == 2) return true;
    if (n % divisor == 0) return false;
    if (divisor * divisor > n) return true;
    // Recursive case
    return isPrime(n, divisor + 1);
}

// Function to reverse the array using recursion
void reverseArray(int arr[], int start, int end) {
    // Base case: when start >= end, no more swaps needed
    if (start >= end) return;
    // Swap the elements at start and end
    int temp = arr[start];
    arr[start] = arr[end];
    arr[end] = temp;
    // Recursive call to reverse the remaining elements
    reverseArray(arr, start + 1, end - 1);
}

int main() {
    int N;
    cout << "Enter the size of the array (must be a prime number >= 2): ";
    cin >> N;

    // Check if N is a prime number
    if (!isPrime(N)) {
        cout << "Error: The size must be a prime number." << endl;
        return 1;
    }

    int arr[N];
    cout << "Enter " << N << " elements:" << endl;
    for (int i = 0; i < N; i++) {
        cin >> arr[i];
    }

    // Reverse the array
    reverseArray(arr, 0, N - 1);

    // Print the reversed array
    cout << "Reversed array:" << endl;
    for (int i = 0; i < N; i++) {
        cout << arr[i] << " ";
    }
    cout << endl;

    return 0;
}
